class Car:
    def __init__(self, make, model, year):
        self.__make = make
        self.__model = model
        self.__year = year

    def getCarAge(self, current_year):
        if self.__year > current_year:
            return -1
        return current_year - self.__year

def main():
    import sys
    data = sys.stdin.read().strip().split()
    if len(data) < 4:
        return

    i = 0
    results = []
    while i + 3 < len(data):
        make = data[i]
        model = data[i + 1]
        year = int(data[i + 2])
        current_year = int(data[i + 3])

        car = Car(make, model, year)
        age = car.getCarAge(current_year)

        if age == -1:
            results.append("Invalid year")
        else:
            results.append(str(age))

        i += 4

    print(" ".join(results))

if __name__ == "__main__":
    main()
